def compute(vars):
    cable_distribution_capex = vars["v1"]
    total_capex = vars["v2"]

    if total_capex == 0:
        return None

    proportion = cable_distribution_capex / total_capex
    percentage = proportion * 100

    return {
        "value": percentage,
        "trace": {
            "cable_distribution_capex": cable_distribution_capex,
            "total_capex": total_capex,
            "proportion": proportion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
